172→    #[test]
173→    fn cache_store_creation() {
174→        let temp = TempDir::new().unwrap();
175→        let store = CacheStore::new(temp.path());
176→
177→        assert_eq!(store.root(), temp.path());
178→    }
179→
180→    #[test]
181→    fn store_and_load() {
182→        let temp = TempDir::new().unwrap();
183→        let store = CacheStore::new(temp.path());
184→
185→        let entry = store
186→            .store("http:test", "template1", "template content", 3600)
187→            .unwrap();
188→
189→        assert_eq!(entry.source_id, "http:test");
190→        assert_eq!(entry.template_name, "template1");
191→
192→        let loaded = store.load("http:test", "template1").unwrap().unwrap();
193→        assert_eq!(loaded.source_id, entry.source_id);
194→        assert_eq!(loaded.template_name, entry.template_name);
195→    }
