197→    #[test]
198→    fn read_content() {
199→        let temp = TempDir::new().unwrap();
200→        let store = CacheStore::new(temp.path());
201→
202→        let entry = store
203→            .store("http:test", "template1", "hello world", 3600)
204→            .unwrap();
205→
206→        let content = store.read_content(&entry).unwrap();
207→        assert_eq!(content, "hello world");
208→    }
209→
210→    #[test]
211→    fn load_nonexistent_returns_none() {
212→        let temp = TempDir::new().unwrap();
213→        let store = CacheStore::new(temp.path());
214→
215→        let result = store.load("http:test", "nonexistent").unwrap();
216→        assert!(result.is_none());
217→    }
218→
219→    #[test]
220→    fn remove_entry() {
221→        let temp = TempDir::new().unwrap();
222→        let store = CacheStore::new(temp.path());
223→
224→        store
225→            .store("http:test", "template1", "content", 3600)
226→            .unwrap();
227→
228→        let removed = store.remove("http:test", "template1").unwrap();
229→        assert!(removed);
230→
231→        let loaded = store.load("http:test", "template1").unwrap();
232→        assert!(loaded.is_none());
233→    }
234→
235→    #[test]
236→    fn remove_nonexistent_returns_false() {
237→        let temp = TempDir::new().unwrap();
238→        let store = CacheStore::new(temp.path());
239→
240→        let removed = store.remove("http:test", "nonexistent").unwrap();
241→        assert!(!removed);
242→    }
243→
244→    #[test]
245→    fn list_entries() {
246→        let temp = TempDir::new().unwrap();
247→        let store = CacheStore::new(temp.path());
248→
249→        store
250→            .store("http:test", "template1", "content1", 3600)
251→            .unwrap();
252→        store
253→            .store("http:test", "template2", "content2", 3600)
254→            .unwrap();
255→
256→        let entries = store.list().unwrap();
257→        assert_eq!(entries.len(), 2);
258→    }
259→
260→    #[test]
261→    fn clear_cache() {
262→        let temp = TempDir::new().unwrap();
263→        let store = CacheStore::new(temp.path());
264→
265→        store
266→            .store("http:test", "template1", "content1", 3600)
267→            .unwrap();
268→        store
269→            .store("http:test", "template2", "content2", 3600)
270→            .unwrap();
271→
272→        let cleared = store.clear().unwrap();
273→        assert_eq!(cleared, 2);
274→
275→        let entries = store.list().unwrap();
276→        assert!(entries.is_empty());
277→    }
278→
279→    #[test]
280→    fn total_size_calculation() {
281→        let temp = TempDir::new().unwrap();
282→        let store = CacheStore::new(temp.path());
283→
284→        store.store("http:test", "t1", "12345", 3600).unwrap(); // 5 bytes
285→        store.store("http:test", "t2", "1234567890", 3600).unwrap(); // 10 bytes
286→
287→        let total = store.total_size().unwrap();
288→        assert_eq!(total, 15);
289→    }
290→
291→    #[test]
292→    fn content_path_is_deterministic() {
293→        let temp = TempDir::new().unwrap();
294→        let store = CacheStore::new(temp.path());
295→
296→        let path1 = store.content_path("http:test", "template");
297→        let path2 = store.content_path("http:test", "template");
298→
299→        assert_eq!(path1, path2);
300→    }
