303→    fn different_entries_have_different_paths() {
304→        let temp = TempDir::new().unwrap();
305→        let store = CacheStore::new(temp.path());
306→
307→        let path1 = store.content_path("http:test", "template1");
308→        let path2 = store.content_path("http:test", "template2");
309→
310→        assert_ne!(path1, path2);
